from urllib.parse import urlencode,quote
from collections import Counter
import json,re,sys,hashlib,csv
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'tools'))
from normalize_calculator_layouts import Document
OUT=ROOT/'docs/clarity-release-2026-10-14'
DATE='2026-10-14'
EVIDENCE={}
COUNTRIES={'US':'United States','CA':'Canada','MX':'Mexico','GB':'United Kingdom','IE':'Ireland','AU':'Australia','NZ':'New Zealand','JP':'Japan'}
def e(value):return escape(str(value),quote=True)
def plain(value):return re.sub(r'\s+',' ',unescape(re.sub(r'<[^>]+>',' ',value))).strip()
def n(value):return 'Unknown' if value is None else f'{value:,.1f}'.rstrip('0').rstrip('.')
def load(path):return json.loads((ROOT/path).read_text(encoding='utf-8'))
REG=load('js/order-registry.json')['records']
def item(market,chain,name,identity=None):
 rows=[r for r in REG if r['market']==market and r['chain']==chain and r['name']==name and r.get('category') not in ['component','sauce']]
 if identity:rows=[r for r in rows if r['id']==identity]
 assert len(rows)==1,(market,chain,name,len(rows))
 row=rows[0];EVIDENCE[row['id']]={k:row.get(k) for k in ['id','chain','market','name','serving','cal','p','c','fat','f','na','source','sourceDate','checked','verificationStatus','calculatedFrom','units','conversions']}
 return row
def grocery(identity):
 for path in (ROOT/'data/branded-foods/retailer-ca/records').glob('*.json'):
  for r in json.loads(path.read_text(encoding='utf-8')):
   if r['id']==identity:
    EVIDENCE[r['id']]={k:r.get(k) for k in ['id','name','brand','market','sourceUrl','sourceChecked','sourceServing','sourcePerServing','nutrients','status','flags']}
    return r
 raise AssertionError(identity)
def portion(r,grams):
 return dict(name=r['brand']+' · '+r['name'],market=r['market'],serving=f'{grams:g} g, calculated from the retailer label',source=r['sourceUrl'],sourceDate=None,checked=r['sourceChecked'],url='/food-library.html?'+urlencode(dict(market=r['market'],food=r['id'])),**{k:(None if r['nutrients'][k] is None else r['nutrients'][k]*grams/100) for k in ['cal','p','c','fat','f','na']})
def total(name,rows):
 return dict(name=name,market=rows[0]['market'],serving=' + '.join(r['serving'] for r in rows)+'; no unnamed extras',source=rows[0]['source'],sourceDate=rows[0].get('sourceDate'),checked=rows[0].get('checked'),url=rows[0]['url'],calculated=True,**{k:sum(r[k] for r in rows) if all(r.get(k) is not None for r in rows) else None for k in ['cal','p','c','fat','f','na']})
def multiply(r,amount,label):
 return {**r,'name':label,'serving':f'{amount:g} × {r["serving"]}; calculated, no drink or extra sides',**{k:None if r.get(k) is None else r[k]*amount for k in ['cal','p','c','fat','f','na']}}
def table(rows,caption,keys=('cal','p','c','fat','f','na')):
 labels=dict(cal='kcal',p='Protein (g)',c='Carbs (g)',fat='Fat (g)',f='Fiber (g)',na='Sodium (mg)')
 return '<p class="table-scroll-note">Scroll across for the full comparison.</p><div class="table-wrap" role="region" tabindex="0" aria-label="'+e(caption)+'"><table><caption>'+e(caption)+'</caption><thead><tr><th scope="col">Food and listed portion</th>'+''.join('<th scope="col">'+labels[k]+'</th>' for k in keys)+'</tr></thead><tbody>'+''.join('<tr><th scope="row">'+e(r['name'])+'<p class="table-portion">'+e(COUNTRIES.get(r['market'],r['market'])+' · '+r['serving'])+'</p></th>'+''.join('<td>'+n(r.get(k))+'</td>' for k in keys)+'</tr>' for r in rows)+'</tbody></table></div>'
def link(url,label):return '<a class="text-action" href="'+e(url)+'">'+e(label)+' →</a>'
def compare(rows,label='Compare these exact foods'):
 # The central workspace consumes stable source IDs, not free-text names.
 if len(rows)>2:label='Compare the first two listed recipes'
 pairs=[('item','order:'+r['market']+':'+r['id']) for r in rows[:2]]+[('basis','portions')]
 return '<p>'+link('/compare-foods.html?'+urlencode(pairs),label)+'</p>'
def sources(rows,extra=()):
 seen={};out=[]
 for r in rows:
  url=r.get('source') or r.get('sourceUrl');key=(url,r.get('sourceDate'),r.get('checked') or r.get('sourceChecked'))
  if key in seen:continue
  seen[key]=True
  label=r.get('chain') or ((r.get('brand','')+' · '+r.get('name','')).strip(' ·')) or 'Official label'
  date=r.get('sourceDate');checked=r.get('checked') or r.get('sourceChecked')
  out.append('<li><a href="'+e(url)+'">'+e(label)+' source</a> · '+('edition '+e(date) if date else 'edition date not stated')+'; record checked '+e(checked or 'date unavailable')+'.</li>')
 for url,label in extra:out.append('<li><a href="'+e(url)+'">'+e(label)+'</a></li>')
 return '<section class="resource-sources"><h2>Sources and serving limits</h2><ul>'+''.join(out)+'</ul></section>'
def article(route,title,desc,cluster,intent,utility,body,rows=(),related=(),overlap='',extra=()):
 return dict(route=route,title=title,description=desc,cluster=cluster,intent=intent,uniqueValue=utility,existingOverlap=overlap,body=body+sources(rows,extra)+'<aside class="source-ribbon"><div><h2>Use this comparison</h2>'+''.join('<p>'+link(url,label)+'</p>' for url,label in related)+'</div></aside>',sourceIds=[r['id'] for r in rows if 'id' in r],status='source-and-arithmetic-checked; no independent clinical or kitchen review',datePublished=DATE)
